UPDATE base_hardness_spec SET
    equip_code = #{equipCode}, product_id = #{productId}, part_no = #{partNo}, product_name = #{productName}, item_name = #{itemName}, unit = #{unit},
    lsl = #{lsl}, usl = #{usl}, target = #{target}, decimals = #{decimals}, sample_size = #{sampleSize},
    use_yn = #{useYn}, remark = #{remark}, upd_user_id = #{updUserId}, upd_user_name = #{updUserName}
WHERE spec_id = #{specId}

mapper.select:
SELECT 
FROM quality_hardness_meas m
JOIN base_hardness_spec s ON s.spec_id = m.spec_id

    AND m.meas_dt >= #{from}
    AND m.meas_dt < #{to}
    AND m.spec_id = #{specId}
    AND m.status = #{status}

        AND (m.meas_no LIKE CONCAT('%', #{keyword}, '%') OR m.part_no LIKE CONCAT('%', #{keyword}, '%')
             OR m.lot_no LIKE CONCAT('%', #{keyword}, '%') OR m.worker_name LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY m.meas_dt DESC, m.meas_id DESC

